import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import { useAuth } from "../contexts/AuthContext";
import LoadingSpinner from "../components/ui/LoadingSpinner";
import CardSkeleton from "../components/ui/SkeletonLoader";
import { PageContainer } from "../components/PageContainer";
import ResponsiveGrid from "../components/ResponsiveGrid";
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  XAxis,
  ResponsiveContainer,
} from "recharts";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import { devices } from "../styles/breakpoints";

export default function Dashboard() {
  const { user } = useAuth();
  const [transactions, setTransactions] = useState([]);
  const [fixedExpenses, setFixedExpenses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [summary, setSummary] = useState({ entradas: 0, saidas: 0, saldo: 0, gastosFixos: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;

    const loadData = async () => {
      try {
        setLoading(true);

        const transSnapshot = await getDocs(collection(db, "users", user.uid, "transactions"));
        const transData = transSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        setTransactions(transData);

        const fixedSnapshot = await getDocs(collection(db, "users", user.uid, "fixed_expenses"));
        const fixedData = fixedSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        setFixedExpenses(fixedData);

        const catSnapshot = await getDocs(collection(db, "users", user.uid, "categories"));
        const catData = catSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        setCategories(catData);

        const entradas = transData
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        const saidas = transData
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saída"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        const gastosFixos = fixedData.reduce((acc, f) => acc + parseFloat(f.value || 0), 0);

        setSummary({ entradas, saidas, saldo: entradas - saidas - gastosFixos, gastosFixos });

      } catch (error) {
        console.error("Erro ao carregar dados:", error);
        alert("Erro ao carregar dados do dashboard");
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [user]);

  const getColorForCategory = (categoryName) => {
    const category = categories.find(cat => cat.name === categoryName);
    return category ? category.color : "#8884d8";
  };

  const expenseMap = {};
  transactions
    .filter((t) => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saída")
    .forEach((t) => {
      const cat = t.category || "Sem categoria";
      if (!expenseMap[cat]) expenseMap[cat] = 0;
      expenseMap[cat] += parseFloat(t.value || 0);
    });
  const expenseDetails = Object.entries(expenseMap).map(([name, value]) => ({
    name,
    value,
    color: getColorForCategory(name, "expense"),
  }));

  const incomeMap = {};
  transactions
    .filter((t) => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada")
    .forEach((t) => {
      const cat = t.category || "Sem categoria";
      if (!incomeMap[cat]) incomeMap[cat] = 0;
      incomeMap[cat] += parseFloat(t.value || 0);
    });
  const incomeDetails = Object.entries(incomeMap).map(([name, value]) => ({
    name,
    value,
    color: getColorForCategory(name, "income"),
  }));

  const fixedColors = ["#3b82f6", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6"];

  const barData = [
    { name: "Entradas", valor: summary.entradas },
    { name: "Saídas", valor: summary.saidas },
    { name: "Gastos Fixos", valor: summary.gastosFixos },
  ];

  const exportToPDF = async () => {
    const dashboard = document.getElementById("dashboard-content");
    if (!dashboard) {
      alert("Erro: não foi possível capturar o dashboard");
      return;
    }

    try {
      const canvas = await html2canvas(dashboard, {
        backgroundColor: "#0f172a",
        scale: 3,
        useCORS: true,
        allowTaint: false,
        scrollX: 0,
        scrollY: 0,
        windowWidth: document.body.scrollWidth,
        windowHeight: document.body.scrollHeight,
        logging: false,
      });

      const imgData = canvas.toDataURL("image/png");
      const pdf = new jsPDF("p", "mm", "a4");

      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();
      const imgWidth = pageWidth - 20;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      pdf.setFillColor("#0f172a");
      pdf.rect(0, 0, pageWidth, 20, "F");
      pdf.setTextColor("#38bdf8");
      pdf.setFontSize(16);
      pdf.text("📊 Relatório Financeiro - CashPilot", 10, 12);

      pdf.setFontSize(10);
      pdf.setTextColor("#f8fafc");
      const date = new Date().toLocaleDateString("pt-BR");
      pdf.text(`Gerado em: ${date}`, pageWidth - 60, 12);

      let yPosition = 25;
      const maxHeight = pageHeight - yPosition - 20;

      if (imgHeight <= maxHeight) {
        pdf.addImage(imgData, "PNG", 10, yPosition, imgWidth, imgHeight);
      } else {
        const scaledHeight = maxHeight;
        const scaledWidth = (imgWidth * scaledHeight) / imgHeight;
        pdf.addImage(imgData, "PNG", (pageWidth - scaledWidth) / 2, yPosition, scaledWidth, scaledHeight);
      }

      pdf.setFontSize(9);
      pdf.setTextColor("#94a3b8");
      pdf.text("CashPilot © 2025 — Seu copiloto financeiro 🚀", 10, pageHeight - 10);

      pdf.save(`CashPilot_Relatorio_${date}.pdf`);
      alert("PDF gerado com sucesso!");
    } catch (error) {
      console.error("Erro ao gerar PDF:", error);
      alert("Erro ao gerar PDF");
    }
  };

  if (loading) {
    return (
      <DashboardContainer>
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="dashboard-loading"
        >
          <PageTitle>
            📊 Dashboard Financeiro
          </PageTitle>
          <LoadingSpinner size="large" className="mt-4" text="Carregando dados..." />

          <SkeletonGrid>
            {Array.from({ length: 4 }, (_, i) => (
              <CardSkeleton key={i} />
            ))}
          </SkeletonGrid>

          <ChartsGrid>
            {Array.from({ length: 4 }, (_, i) => (
              <CardSkeleton key={i} />
            ))}
          </ChartsGrid>
        </motion.div>
      </DashboardContainer>
    );
  }

  return (
    <DashboardContainer>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="dashboard-content"
      >
        <div id="dashboard-content">
          <HeaderSection>
            <div>
              <PageTitle>
                📊 Dashboard Financeiro
              </PageTitle>
              <PageSubtitle>
                Visão geral dos seus gastos e receitas
              </PageSubtitle>
            </div>

            <PDFButton
              onClick={exportToPDF}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              📄 Exportar PDF
            </PDFButton>
          </HeaderSection>

          {/* Cards de Resumo */}
          <ResponsiveGrid $columns={4} $gap="1rem">
            <SummaryCard
              color="green"
              whileHover={{ scale: 1.02, y: -2 }}
            >
              <CardContent>
                <CardInfo>
                  <CardLabel color="green">Total Entradas</CardLabel>
                  <CardValue>R$ {summary.entradas.toFixed(2)}</CardValue>
                </CardInfo>
                <CardIcon>💰</CardIcon>
              </CardContent>
            </SummaryCard>

            <SummaryCard
              color="red"
              whileHover={{ scale: 1.02, y: -2 }}
            >
              <CardContent>
                <CardInfo>
                  <CardLabel color="red">Total Saídas</CardLabel>
                  <CardValue>R$ {summary.saidas.toFixed(2)}</CardValue>
                </CardInfo>
                <CardIcon>💸</CardIcon>
              </CardContent>
            </SummaryCard>

            <SummaryCard
              color="blue"
              whileHover={{ scale: 1.02, y: -2 }}
            >
              <CardContent>
                <CardInfo>
                  <CardLabel color="blue">Gastos Fixos</CardLabel>
                  <CardValue>R$ {summary.gastosFixos.toFixed(2)}</CardValue>
                </CardInfo>
                <CardIcon>🏠</CardIcon>
              </CardContent>
            </SummaryCard>

            <SummaryCard
              color={summary.saldo >= 0 ? "emerald" : "orange"}
              whileHover={{ scale: 1.02, y: -2 }}
            >
              <CardContent>
                <CardInfo>
                  <CardLabel color={summary.saldo >= 0 ? "emerald" : "orange"}>Saldo Atual</CardLabel>
                  <CardValue>R$ {summary.saldo.toFixed(2)}</CardValue>
                </CardInfo>
                <CardIcon>{summary.saldo >= 0 ? '📈' : '📉'}</CardIcon>
              </CardContent>
            </SummaryCard>
          </ResponsiveGrid>

          {/* Gráficos */}
          <ChartsContainer>
            <ChartCard>
              <ChartTitle>📈 Resumo Geral</ChartTitle>
              <ResponsiveContainer width="100%" height={250}>
                <BarChart data={barData}>
                  <XAxis
                    dataKey="name"
                    tick={{ fill: "#cbd5e1", fontSize: 12 }}
                    tickLine={false}
                  />
                  <Tooltip
                    cursor={{ fill: "rgba(56, 189, 248, 0.1)" }}
                    contentStyle={{
                      background: "#1e293b",
                      border: "1px solid #38bdf8",
                      borderRadius: "8px",
                      color: "#f8fafc"
                    }}
                  />
                  <Bar dataKey="valor" radius={[8, 8, 0, 0]}>
                    {barData.map((entry, index) => (
                      <Cell
                        key={`bar-${index}`}
                        fill={index === 0 ? "#22c55e" : index === 1 ? "#ef4444" : "#3b82f6"}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </ChartCard>

            <ChartCard>
              <ChartTitle>📊 Saídas por Categoria</ChartTitle>
              <ResponsiveContainer width="100%" height={250}>
                <PieChart>
                  <Pie
                    data={expenseDetails}
                    dataKey="value"
                    nameKey="name"
                    outerRadius={80}
                    animationBegin={0}
                    animationDuration={800}
                  >
                    {expenseDetails.map((_, index) => (
                      <Cell key={`slice-${index}`} fill={expenseDetails[index].color} />
                    ))}
                  </Pie>
                  <Tooltip
                    contentStyle={{
                      background: "#1e293b",
                      border: "1px solid #38bdf8",
                      borderRadius: "8px",
                      color: "#f8fafc"
                    }}
                  />
                  <Legend
                    wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </ChartCard>

            <ChartCard>
              <ChartTitle>💰 Entradas por Categoria</ChartTitle>
              <ResponsiveContainer width="100%" height={250}>
                <PieChart>
                  <Pie
                    data={incomeDetails}
                    dataKey="value"
                    nameKey="name"
                    outerRadius={80}
                    animationBegin={0}
                    animationDuration={800}
                  >
                    {incomeDetails.map((_, index) => (
                      <Cell key={`slice-${index}`} fill={incomeDetails[index].color} />
                    ))}
                  </Pie>
                  <Tooltip
                    contentStyle={{
                      background: "#1e293b",
                      border: "1px solid #38bdf8",
                      borderRadius: "8px",
                      color: "#f8fafc"
                    }}
                  />
                  <Legend
                    wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </ChartCard>

            <ChartCard>
              <ChartTitle>🏠 Gastos Fixos</ChartTitle>
              <ResponsiveContainer width="100%" height={250}>
                <PieChart>
                  <Pie
                    data={fixedExpenses.map((f) => ({ name: f.name, value: parseFloat(f.value || 0) }))}
                    dataKey="value"
                    nameKey="name"
                    outerRadius={80}
                    animationBegin={0}
                    animationDuration={800}
                  >
                    {fixedExpenses.map((_, index) => (
                      <Cell key={`slice-${index}`} fill={fixedColors[index % fixedColors.length]} />
                    ))}
                  </Pie>
                  <Tooltip
                    contentStyle={{
                      background: "#1e293b",
                      border: "1px solid #38bdf8",
                      borderRadius: "8px",
                      color: "#f8fafc"
                    }}
                  />
                  <Legend
                    wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </ChartCard>
          </ChartsContainer>
        </div>
      </motion.div>
    </DashboardContainer>
  );
}

// ============= STYLES =============

const DashboardContainer = styled.div`
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--space-sm);

  @media (min-width: 768px) {
    padding: var(--space-md);
  }
`;

const PageTitle = styled.h1`
  font-size: clamp(1.5rem, 5vw, 2.25rem);
  font-weight: bold;
  margin-bottom: var(--space-sm);
  background: linear-gradient(135deg, #38bdf8, #0ea5e9);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
`;

const PageSubtitle = styled.p`
  color: #94a3b8;
  font-size: var(--fs-sm);
  margin-bottom: var(--space-lg);

  @media (min-width: 768px) {
    font-size: var(--fs-base);
  }
`;

const HeaderSection = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  margin-bottom: var(--space-lg);

  @media (min-width: 768px) {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
`;

const PDFButton = styled.button`
  background: linear-gradient(135deg, #38bdf8, #0ea5e9);
  color: #0f172a;
  font-weight: 600;
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s;
  font-size: var(--fs-sm);
  min-height: 44px;
  align-self: flex-start;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(56, 189, 248, 0.4);
  }

  @media (min-width: 768px) {
    align-self: auto;
  }
`;

const SummaryGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);

  @media (min-width: 480px) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (min-width: 1024px) {
    grid-template-columns: repeat(4, 1fr);
  }
`;

const SummaryCard = styled(motion.div)`
  background: ${props => {
    switch (props.color) {
      case 'green':
        return 'linear-gradient(135deg, rgba(34, 197, 94, 0.2), rgba(34, 197, 94, 0.05))';
      case 'red':
        return 'linear-gradient(135deg, rgba(239, 68, 68, 0.2), rgba(239, 68, 68, 0.05))';
      case 'blue':
        return 'linear-gradient(135deg, rgba(59, 130, 246, 0.2), rgba(59, 130, 246, 0.05))';
      case 'emerald':
        return 'linear-gradient(135deg, rgba(16, 185, 129, 0.2), rgba(16, 185, 129, 0.05))';
      case 'orange':
        return 'linear-gradient(135deg, rgba(249, 115, 22, 0.2), rgba(249, 115, 22, 0.05))';
      default:
        return 'rgba(30, 41, 59, 0.5)';
    }
  }};
  border: 1px solid ${props => {
    switch (props.color) {
      case 'green': return 'rgba(34, 197, 94, 0.3)';
      case 'red': return 'rgba(239, 68, 68, 0.3)';
      case 'blue': return 'rgba(59, 130, 246, 0.3)';
      case 'emerald': return 'rgba(16, 185, 129, 0.3)';
      case 'orange': return 'rgba(249, 115, 22, 0.3)';
      default: return 'rgba(148, 163, 184, 0.1)';
    }
  }};
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  cursor: pointer;
  min-height: 100px;

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const CardContent = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
`;

const CardInfo = styled.div`
  flex: 1;
  min-width: 0;
`;

const CardLabel = styled.p`
  font-size: var(--fs-sm);
  color: ${props => {
    switch (props.color) {
      case 'green': return '#86efac';
      case 'red': return '#fca5a5';
      case 'blue': return '#93c5fd';
      case 'emerald': return '#6ee7b7';
      case 'orange': return '#fdba74';
      default: return '#cbd5e1';
    }
  }};
  margin-bottom: var(--space-xs);
  font-weight: 500;
`;

const CardValue = styled.p`
  font-size: clamp(1.25rem, 4vw, 1.75rem);
  font-weight: bold;
  color: #f8fafc;
  word-break: break-word;
`;

const CardIcon = styled.div`
  font-size: clamp(1.5rem, 5vw, 2rem);
  flex-shrink: 0;
`;

const ChartsContainer = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (min-width: 1280px) {
    gap: var(--space-lg);
  }
`;

const ChartsGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-top: var(--space-lg);

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
`;

const SkeletonGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-bottom: var(--space-lg);

  @media (min-width: 480px) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (min-width: 1024px) {
    grid-template-columns: repeat(4, 1fr);
  }
`;

const ChartCard = styled.div`
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  backdrop-filter: blur(8px);

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const ChartTitle = styled.h3`
  font-size: var(--fs-base);
  color: #e2e8f0;
  margin-bottom: var(--space-md);
  text-align: center;
  font-weight: 600;

  @media (min-width: 768px) {
    font-size: var(--fs-lg);
  }
`;
